INSERT OR IGNORE INTO "recommendation_evidence" ("id", "recommendation_id", "imported_vibe_post_id", "evidence_comment_id", "extracted_text", "confidence", "is_primary", "created_at", "evidence_comment_score") VALUES (39533, 4602, 1610, 'p2sh7vl', '**Night of the Comet** is a really fun post-apocalyptic romp following two sisters.

**All of Us Strangers** is one of the most heartwrenching films I’ve ever seen.

**Manhunter** is basically Silence of the Lambs in the style of Miami Vice.

**Andromeda Strain** is a stylized sci fi that really respects the audience’s intelligence.

**Three Ages** is one of my favorite silent films, Buster Keaton’s slapstick romance homage to Griffith’s Intolerance.', NULL, 0, '2026-08-11 22:09:33', 4);
